import React from "react";
import "./AdminPanel.css";

function AdminPanel() {
  return (
    <div className="admin">
      <h1>Admin Panel</h1>

      <div className="admin-section">
        <h3>Manage Orders</h3>
        <p>Update order status and tracking details.</p>
        <button>View Orders</button>
      </div>

      <div className="admin-section">
        <h3>System Analytics</h3>
        <p>Monitor shipments and payment status.</p>
        <button>View Reports</button>
      </div>
    </div>
  );
}

export default AdminPanel;
